function minLengthAfterRemovals(nums) {
  const n = nums.length;
  let maxCount = 0;
  let run = 0;

  for (let i = 0; i < n; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) {
      run++;
    } else {
      run = 1;
    }
    maxCount = Math.max(maxCount, run);
  }

  const others = n - maxCount;
  if (maxCount > others) {
    return maxCount - others;
  }
  return n % 2;
}

