function minLengthAfterRemovals(nums) {
  // Try every legal removal from every reachable array, remembering results.
  const memo = new Map();
  const search = (arr) => {
    const key = arr.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = arr.length;
    for (let i = 0; i < arr.length; i++) {
      for (let j = 0; j < arr.length; j++) {
        if (arr[i] < arr[j]) {
          const rest = arr.filter((_, k) => k !== i && k !== j);
          best = Math.min(best, search(rest));
        }
      }
    }
    memo.set(key, best);
    return best;
  };
  return search(nums.slice());
}

