function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const span = size === 'large' ? 1000000000 : 1 + Math.floor(rand() * 5);
  const nums = [];
  const mode = rand();
  if (mode < 0.4) {
    // One value dominates a chosen share of the array.
    const share = 0.3 + rand() * 0.7;
    const big = 1 + Math.floor(rand() * span);
    for (let i = 0; i < n; i++) nums.push(rand() < share ? big : 1 + Math.floor(rand() * span));
  } else {
    for (let i = 0; i < n; i++) nums.push(1 + Math.floor(rand() * span));
  }
  nums.sort((a, b) => a - b);
  return [nums];
}
